  \centering
  \small
  \begin{tabular}{lll}
    \toprule
    \textbf{Family} & \textbf{Sizes} & \textbf{Versions} \\
    \midrule
    Gemma 2       & 2B, 9B, 27B   & base and instruct \\
    Gemma 3       & 27B           & base and instruct \\
    Llama 3.1     & 8B, 70B       & base and instruct \\
